const by = `{"licenses": {"*": {"spdx": "CC-BY-4.0", "attribution": "Test Artist", "source": "https://example.org/src"}}}`

// song writes a dummy song folder (generated bytes, no real content).
func song(feed, catalog, folder, txt string, headers map[string]string, meta string, files ...string) string {
	dir := filepath.Join(feed, "songs", catalog, folder)
	os.MkdirAll(dir, 0o755)
	var b strings.Builder
	for _, k := range []string{"ARTIST", "TITLE", "BPM", "GAP", "MP3", "COVER", "VIDEO", "BACKGROUND"} {
		if v, ok := headers[k]; ok {
			b.WriteString("#" + k + ":" + v + "\n")
		}
	}
	b.WriteString(": 0 4 60 la\n: 8 4 62 la\nE\n")
	os.WriteFile(filepath.Join(dir, txt), []byte(b.String()), 0o644)
	for _, f := range files {
		os.WriteFile(filepath.Join(dir, f), []byte(strings.Repeat("dummy "+folder+f, 100)), 0o644)
	}
	if meta != "" {
		os.WriteFile(filepath.Join(dir, metaName), []byte(meta), 0o644)
	}
	return dir
}

func h(artist, title, mp3 string) map[string]string {
	return map[string]string{"ARTIST": artist, "TITLE": title, "BPM": "300", "GAP": "0", "MP3": mp3}
}

func run(dir, key string, mass bool) (string, error) {
	var out bytes.Buffer
	err := build(dir, "", key, false, mass, false, &out)
	return out.String(), err
}

func must(t *testing.T, out string, err error, wants ...string) {
	t.Helper()
	if err != nil {
		t.Fatalf("unexpected error: %v\n%s", err, out)
	}
	for _, w := range wants {
		if !strings.Contains(out, w) {
			t.Fatalf("output lacks %q:\n%s", w, out)
		}
	}
}

func fails(t *testing.T, err error, want string) {
	t.Helper()
	if err == nil || !strings.Contains(err.Error(), want) {
		t.Fatalf("want an error containing %q, got: %v", want, err)
	}
}

func problems(s source, key string, full bool) string {
	c := &checker{}
	verify(s, key, full, c)
	return strings.Join(c.errs, "\n")
}

func newKey(t *testing.T, path string) string {
	t.Helper()
	if err := cmdKeygen([]string{path}); err != nil {
		t.Fatal(err)
	}
	priv, err := loadKey(path)
	if err != nil {
		t.Fatal(err)
	}
	return pubString(priv.Public().(ed25519.PublicKey))
}

func config(dir string, keys ...string) {
	q := ""
	if len(keys) > 0 {
		q = `"` + strings.Join(keys, `","`) + `"`
	}
	os.WriteFile(filepath.Join(dir, configName), []byte(`{"name":"Test Feed","operator":{"name":"Tester","contact":"mailto:takedown@example.com"},"keys":[`+q+`]}`), 0o644)
}

func TestOperatorWorkflow(t *testing.T) {
	dir := t.TempDir()
	keys := t.TempDir()
	k1, k2, k3 := filepath.Join(keys, "feed.key"), filepath.Join(keys, "backup.key"), filepath.Join(keys, "new.key")
	p1, p2, p3 := newKey(t, k1), newKey(t, k2), newKey(t, k3)
	if cmdKeygen([]string{k1}) == nil {
		t.Fatal("keygen must not overwrite an existing key")
	}
	if err := cmdInit([]string{dir}); err != nil {
		t.Fatal(err)
	}
	_, err := run(dir, "", false)
	fails(t, err, "operator") // the template must be filled in first
	config(dir, p1, p2)
	pub := filepath.Join(dir, "public")

	lied := h("Künstler", "Lied", "Künstler - Lied.mp3")
	lied["COVER"], lied["VIDEO"] = "Künstler - Lied [CO].jpg", "Künstler - Lied.mp4"
	song(dir, "Pop Songs", "Künstler - Lied", "Künstler - Lied.txt", lied, by, "Künstler - Lied.mp3", "Künstler - Lied [CO].jpg", "Künstler - Lied.mp4")
	song(dir, "Pop Songs", "Künstler - Lied", "Künstler - Lied [DUET].txt", h("Künstler", "Lied [DUET]", "Künstler - Lied.mp3"), "")
	legacy := h("Cafe Band", "Ete", "cafe.mp3")
	legacy["COVER"], legacy["BACKGROUND"] = "Cover.JPG", "missing.png"
	song(dir, "Pop Songs", "Legacy", "legacy.txt", legacy, by, "cafe.mp3", "cover.jpg")
	song(dir, "Pop Songs", "Undeclared", "u.txt", h("Nobody", "Unknown", "u.mp3"), "", "u.mp3")
	song(dir, "Pop Songs", "Bad", "bad.txt", h("Bad", "Traversal", "../evil.mp3"), by)
	song(dir, "Pop Songs", "Exe", "exe.txt", h("Bad", "Type", "song.exe"), by, "song.exe")
	takedown := song(dir, "Pop Songs", "Takedown", "t.txt", h("Take", "Down", "t.mp3"), by, "t.mp3")
	song(dir, "Rock", "One", "one.txt", h("One", "One", "one.mp3"), by, "one.mp3")

	_, err = run(dir, "", false)
	fails(t, err, "pass --key")
	_, err = run(dir, k3, false)
	fails(t, err, "not listed")

	out, err := run(dir, k1, false)
	must(t, out, err, "First build: 6 songs", "signed by "+p1, "catalog pop-songs", "catalog rock",
		"Hidden by default in clients, no license declared (1): nobody-unknown",
		"NOT PUBLISHED, fix these (2)", `"../evil.mp3" contains one of`, `not allowed for role audio`,
		"only by upper/lower case", `"missing.png" is missing`)
	if p := problems(newSource(pub), p1, true); p != "" {
		t.Fatalf("fresh build does not verify:\n%s", p)
	}

	out, err = run(dir, k1, false)
	must(t, out, err, "No changes since the last build")

	// edit, add, delist
	f, _ := os.OpenFile(filepath.Join(dir, "songs", "Rock", "One", "one.txt"), os.O_APPEND|os.O_WRONLY, 0)
	f.WriteString("# fixed timing\n")
	f.Close()
	song(dir, "Rock", "Two", "two.txt", h("Two", "Two", "two.mp3"), by, "two.mp3")
	os.RemoveAll(filepath.Join(dir, "songs", "Pop Songs", "Legacy"))
	out, err = run(dir, k1, false)
	must(t, out, err, "+ added (1): two-two", "~ changed (1): one-one", "- delisted (clients hide them, cached files stay) (1): cafe-band-ete", "unused files deleted")

	// withdraw (takedown)
	os.WriteFile(filepath.Join(dir, removedName), []byte("# takedowns, newest last\ntake-down   # Take – Down: takedown request 2026-11-14\n"), 0o644)
	_, err = run(dir, k1, false)
	fails(t, err, "still in the songs folder")
	sum, _, _ := hashFile(filepath.Join(takedown, "t.mp3"))
	os.RemoveAll(takedown)
	out, err = run(dir, k1, false)
	must(t, out, err, "x withdrawn (clients delete them) (1): take-down", "purge them from CDN caches", "blobs/"+sum[:2]+"/"+sum)
	if _, err := os.Stat(filepath.Join(pub, "blobs", sum[:2], sum)); err == nil {
		t.Fatal("the withdrawn song's audio is still in the published folder")
	}
	if raw, _ := os.ReadFile(filepath.Join(pub, "feed.json")); !strings.Contains(string(raw), `"take-down"`) {
		t.Fatal("feed.json does not list the withdrawn id")
	}

	// rename: hint first, then previous_ids
	two := filepath.Join(dir, "songs", "Rock", "Two")
	song(dir, "Rock", "Two", "two.txt", h("Two", "Two (Live)", "two.mp3"), by)
	out, err = run(dir, k1, false)
	must(t, out, err, "Renamed?", `"previous_ids": ["two-two"]`)
	os.WriteFile(filepath.Join(two, metaName), []byte(strings.Replace(by, "{", `{"previous_ids": ["two-two"], `, 1)), 0o644)
	out, err = run(dir, k1, false)
	must(t, out, err, "no song changed")
	if p := problems(newSource(pub), "", true); p != "" {
		t.Fatalf("does not verify after edits:\n%s", p)
	}

	// a songs folder that lost most of its content must not be published by accident
	for _, n := range []string{"a", "b", "c", "d", "e", "f", "g"} {
		song(dir, "Bulk", n, n+".txt", h("Bulk", n, n+".mp3"), by, n+".mp3")
	}
	out, err = run(dir, k1, false)
	must(t, out, err, "+ added (7)")
	os.RemoveAll(filepath.Join(dir, "songs", "Bulk"))
	_, err = run(dir, k1, false)
	fails(t, err, "--allow-mass-removal")
	out, err = run(dir, k1, true)
	must(t, out, err, "- delisted")

	// tampering and damage are found
	feedFile := filepath.Join(pub, "feed.json")
	good, _ := os.ReadFile(feedFile)
	os.WriteFile(feedFile, bytes.Replace(good, []byte("Test Feed"), []byte("Evil Feed"), 1), 0o644)
	if p := problems(newSource(pub), "", false); !strings.Contains(p, "signature") {
		t.Fatalf("tampered feed.json not detected: %q", p)
	}
	os.WriteFile(feedFile, good, 0o644)
	oneSum, _, _ := hashFile(filepath.Join(dir, "songs", "Rock", "One", "one.mp3"))
	blob := filepath.Join(pub, "blobs", oneSum[:2], oneSum)
	os.Remove(blob) // it is a hard link to the source file; replace it instead of writing through it
	os.WriteFile(blob, []byte("damaged"), 0o644)
	if p := problems(newSource(pub), "", false); !strings.Contains(p, "bytes, the catalog says") {
		t.Fatalf("damaged blob not detected: %q", p)
	}
	os.Remove(blob)
	out, err = run(dir, k1, false)
	must(t, out, err, "No changes since the last build")
	if p := problems(newSource(pub), "", true); p != "" {
		t.Fatalf("a rebuild must restore missing blobs:\n%s", p)
	}

	// key rotation: the backup key takes over, the old key is dropped
	config(dir, p2, p3)
	out, err = run(dir, k2, false)
	must(t, out, err, "signed by "+p2)
	if p := problems(newSource(pub), p2, false); p != "" {
		t.Fatalf("feed signed by the backup key does not verify:\n%s", p)
	}
	if p := problems(newSource(pub), p1, false); !strings.Contains(p, "signature") {
		t.Fatal("the feed still verifies under the retired key")
	}

	// served over http: same result, range requests and headers in place
	srv := httptest.NewServer(feedHandler(pub))
	defer srv.Close()
	c := &checker{}
	verify(newSource(srv.URL+"/feed.json"), p2, true, c)
	if len(c.errs) > 0 {
		t.Fatalf("http verify failed:\n%s", strings.Join(c.errs, "\n"))
	}
	for _, w := range c.warns {
		if strings.Contains(w, "range") || strings.Contains(w, "Cache-Control") || strings.Contains(w, "Access-Control") {
			t.Fatalf("kfeed serve should not cause this warning: %s", w)
		}
	}

	// a CDN in front that does not cache is reported
	cdn := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("CF-Cache-Status", "DYNAMIC")
		feedHandler(pub).ServeHTTP(w, r)
	}))
	defer cdn.Close()
	c = &checker{}
	verify(newSource(cdn.URL+"/feed.json"), p2, false, c)
	if w := strings.Join(c.warns, "\n"); !strings.Contains(w, "Cloudflare does not cache blobs") || !strings.Contains(w, "Cloudflare does not cache feed.json") {
		t.Fatalf("missing CDN cache warnings:\n%s", w)
	}

	// files over Cloudflare's cache limit are reported
	big := filepath.Join(dir, "songs", "Rock", "One", "one.mp4")
	if f, err := os.Create(big); err == nil {
		f.Truncate(513 << 20) // sparse: no real disk space
		f.Close()
	}
	one := h("One", "One", "one.mp3")
	one["VIDEO"] = "one.mp4"
	song(dir, "Rock", "One", "one.txt", one, by)
	out, err = run(dir, k2, false)
	must(t, out, err, "does not cache files over 512 MB")

	// never write a feed into a folder that is something else
	other := t.TempDir()
	os.WriteFile(filepath.Join(other, "holiday.jpg"), []byte("x"), 0o644)
	var buf bytes.Buffer
	fails(t, build(dir, other, k2, false, false, false, &buf), "refusing")
}

func TestNames(t *testing.T) {
	bad := map[string]string{"../x.mp3": "audio", `..\x.mp3`: "audio", "/etc/x.mp3": "audio", "CON.mp3": "audio", "nul.tar.mp3": "audio",
		"a.mp3.": "audio", "a.mp3 ": "audio", ".hidden.mp3": "audio", " a.mp3": "audio", "a:b.mp3": "audio", "a?.mp3": "audio",
		"a\x01.mp3": "audio", "evil.exe": "audio", "song.mp3": "cover", "noext": "audio", "": "audio", strings.Repeat("a", 157) + ".mp3": "audio",
		"a.mp3": "other"}
	for name, role := range bad {
		if nameProblem(name, role) == "" {
			t.Errorf("%q (%s) should be rejected", name, role)
		}
	}
	for name, role := range map[string]string{"Künstler - Lied [CO].jpg": "cover", "Song (feat. X) #1.MP3": "audio", "a.txt": "txt", "license.txt": "license", "console.mp3": "audio"} {
		if p := nameProblem(name, role); p != "" {
			t.Errorf("%q (%s) should be accepted: %s", name, role, p)
		}
	}
}

func TestSlugAndLicenseURL(t *testing.T) {
	for in, want := range map[string]string{"Künstler-Lied [DUET]": "kunstler-lied-duet", "Café Band-Été": "cafe-band-ete", "  A  &  B  ": "a-b", "日本語": ""} {
		if got := slug(in); got != want {
			t.Errorf("slug(%q) = %q, want %q", in, got, want)
		}
	}
	for in, want := range map[string]string{"CC-BY-NC-SA-3.0": "https://creativecommons.org/licenses/by-nc-sa/3.0/", "CC0-1.0": "https://creativecommons.org/publicdomain/zero/1.0/",
		"CC-BY-3.0-DE": "https://creativecommons.org/licenses/by/3.0/de/", "MIT": ""} {
		if got := ccURL(in); got != want {
			t.Errorf("ccURL(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestKeyHandling(t *testing.T) {
	dir := t.TempDir()
	keyFile := filepath.Join(dir, "feed.key")
	pub := newKey(t, keyFile)
	pem, _ := os.ReadFile(keyFile)

	// from standard input: the key never needs to touch the disk unencrypted
	stdin = bytes.NewReader(pem)
	defer func() { stdin = os.Stdin }()
	if k, err := loadKey("-"); err != nil || pubString(k.Public().(ed25519.PublicKey)) != pub {
		t.Fatalf("key from standard input: %v", err)
	}

	// a key file other users can read is refused (not checked on Windows, which uses ACLs)
	if runtime.GOOS != "windows" {
		os.Chmod(keyFile, 0o644)
		if _, err := loadKey(keyFile); err == nil || !strings.Contains(err.Error(), "chmod 600") {
			t.Fatalf("readable key file accepted: %v", err)
		}
		os.Chmod(keyFile, 0o600)
	}
	if _, err := loadKey(keyFile); err != nil {
		t.Fatal(err)
	}

	// public keys for sync and verify: as text or from a file; a private key file there is refused with a hint
	pubFile := filepath.Join(dir, "feed.pub")
	os.WriteFile(pubFile, []byte(pub+"\n"), 0o644)
	for _, arg := range []string{pub, pubFile} {
		if got, err := publicKeyArg(arg); err != nil || got != pub {
			t.Errorf("publicKeyArg(%q) = %q, %v", arg, got, err)
		}
	}
	if _, err := publicKeyArg(keyFile); err == nil || !strings.Contains(err.Error(), "kfeed pubkey") {
		t.Errorf("private key file accepted as public key: %v", err)
	}
	if _, err := publicKeyArg(filepath.Join(dir, "missing")); err == nil {
		t.Error("missing file accepted")
	}
}

// The catalog and signature of the previous build stay for one more build, so that a client that has just fetched the
// old feed.json still finds them. The build after that removes them, also when nothing changed.
func TestOutdatedFilesRemoved(t *testing.T) {
	dir, keys := t.TempDir(), t.TempDir()
	k := filepath.Join(keys, "feed.key")
	config(dir, newKey(t, k))
	pub := filepath.Join(dir, "public")
	count := func(sub string) int {
		entries, _ := os.ReadDir(filepath.Join(pub, sub))
		return len(entries)
	}
	song(dir, "Pop", "a", "a.txt", h("A", "One", "a.mp3"), by, "a.mp3")
	rebuild(t, dir, k)
	song(dir, "Pop", "b", "b.txt", h("B", "Two", "b.mp3"), by, "b.mp3")
	rebuild(t, dir, k)
	if count("catalog") != 2 || count("sig") != 2 {
		t.Fatalf("after a change: %d catalogs, %d signatures, want 2 and 2", count("catalog"), count("sig"))
	}
	out, err := run(dir, k, false)
	must(t, out, err, "No changes", "Removed 2 outdated file(s)")
	if count("catalog") != 1 || count("sig") != 1 {
		t.Fatalf("after the next build: %d catalogs, %d signatures, want 1 and 1", count("catalog"), count("sig"))
	}
	if p := problems(newSource(pub), "", true); p != "" {
		t.Fatalf("the feed is damaged after the cleanup: %s", p)
	}
	out, err = run(dir, k, false)
	must(t, out, err, "No changes")
	if strings.Contains(out, "Removed") {
		t.Fatalf("a third build removed something again:\n%s", out)
	}
}
